INSERT INTO products (slug, title_tr, title_en, description_tr, description_en, category, collection, medium_tr, medium_en, dimensions_tr, dimensions_en, subject_tr, subject_en, artist_id, sort_order, is_visible) VALUES ('anka-i-ates-ve-donusum', 'Anka I – Ateş ve Dönüşüm', 'Anka I – Fire and Transformation', 'Anka’nın yükselen ve yeniden doğan varlığından esinlenen bu çalışma, kuş imgesini doğrudan betimlemek yerine soyut ve akışkan bir forma dönüştürür. Yukarı doğru uzanan gövde ve kanatları çağrıştıran keskin kıvrımlar, yükseliş ve dönüşüm duygusunu taşırken; kırmızı ve ateş tonlarındaki yüzey Anka’nın ateşle kurduğu mitolojik bağı güçlendirir. Form, yok oluşun ardından yeniden var olmayı ve yaşamın sürekli dönüşümünü simgeler.
INSERT INTO products (slug, title_tr, title_en, description_tr, description_en, category, collection, medium_tr, medium_en, dimensions_tr, dimensions_en, subject_tr, subject_en, artist_id, sort_order, is_visible) VALUES ('anka-ii-karanliktan-yukselis', 'Anka II – Karanlıktan Yükseliş', 'Anka II – Rising from the Dark', 'Anka’nın mitolojik varlığını soyut bir kuş formu üzerinden yorumlayan bu çalışma, uzun ve yukarı yönelen gövdesiyle yeniden doğuşun ardından gelen yükseliş anına odaklanır. Kanadı çağrıştıran geniş yüzey ile ince, kıvrımlı boyun arasında kurulan karşıtlık, forma hem durağanlık hem de hareket duygusu kazandırır. Koyu metalik yüzeyde beliren yeşil ve ışıltılı tonlar, Anka’nın ateşten geçerek başka bir varoluşa dönüşmesini çağrıştırır. Anka II, dönüşümden sonra yeniden güç kazanmayı ve karanlığın içinden yükselen yaşamı simgeler.
INSERT INTO products (slug, title_tr, title_en, description_tr, description_en, category, collection, medium_tr, medium_en, dimensions_tr, dimensions_en, subject_tr, subject_en, artist_id, sort_order, is_visible) VALUES ('anka-iii-yasama-donus', 'Anka III – Yaşama Dönüş', 'Anka III – Return to Life', 'Anka’nın yeniden doğuş döngüsünü sürdüren bu çalışma, yükselen gövdesi ve dışa doğru açılan katmanlı kanatlarıyla yaşamın yeniden hareket kazanmasını çağrıştırır. Toprak, kehribar ve yanık kahve tonlarının yüzeyde birbirine karışması, ateşten geçen varlığın yeniden doğayla bütünleşmesini simgeler. Gövdeden farklı yönlere uzanan kıvrımlı formlar, dönüşümün ardından açılmayı, güçlenmeyi ve yeni bir yaşama yönelmeyi ifade eder. Anka III, yeniden doğan varlığın dünyaya dönüşünü ve yaşamın sürekliliğini temsil eder.
INSERT INTO products (slug, title_tr, title_en, description_tr, description_en, category, collection, medium_tr, medium_en, dimensions_tr, dimensions_en, subject_tr, subject_en, artist_id, sort_order, is_visible) VALUES ('anka-iv-ozgurlesme', 'Anka IV – Özgürleşme', 'Anka IV – Liberation', 'Anka’nın yeniden doğuş döngüsünün tamamlandığı bu çalışma, yükselen gövdesi ve farklı yönlere açılan kanat ve kuyruk parçalarıyla özgürleşme ve hareket duygusunu öne çıkarır. Gövdeden çoğalarak dışarıya uzanan sivri formlar, içsel bir enerjinin açığa çıkışını ve yeniden kazanılan yaşam gücünü çağrıştırır. Topraksı ve koyu yüzey, Anka’nın ateşten ve dönüşümden taşıdığı izleri korurken; yukarı yönelen baş ve açılan kanatlar yeni bir başlangıca işaret eder. Anka IV, dönüşümünü tamamlayan varlığın özgürleşmesini ve yeniden yaşamın içine yükselişini simgeler.
INSERT INTO products (slug, title_tr, title_en, description_tr, description_en, category, collection, medium_tr, medium_en, dimensions_tr, dimensions_en, subject_tr, subject_en, artist_id, sort_order, is_visible) VALUES ('anka-v-yeniden-varolus', 'Anka V – Yeniden Varoluş', 'Anka V – Renewed Existence', 'Anka’nın dönüşüm yolculuğunda yeni bir başlangıcı temsil eden bu çalışma, açık renkli yüzeyi ve katmanlar hâlinde yükselen kanatlarıyla serinin önceki parçalarından ayrılır. Gövde üzerinde görülen çatlaklar ve yüzey izleri, geçmişin silinmediği; yeniden doğan varlığın belleğinde yaşamaya devam ettiği düşüncesini taşır. Yukarı doğru uzanan boyun ve açılarak çoğalan kanatlar ise yeniden doğuşun ardından gelen hafifleme, özgürleşme ve yükselme duygusunu güçlendirir. Anka V, geçmişin izlerini taşıyarak yeniden başlayan yaşamı simgeler.
INSERT INTO products (slug, title_tr, title_en, description_tr, description_en, category, collection, medium_tr, medium_en, dimensions_tr, dimensions_en, subject_tr, subject_en, artist_id, sort_order, is_visible) VALUES ('sahmaran-i-donusum', 'Şahmaran I – Dönüşüm', 'Şahmaran I – Transformation', 'Şahmaran, Anadolu''nun sözlü kültüründe yüzyıllardır yaşayan; bilgelik, doğa, şifa, sır ve dönüşüm kavramlarıyla ilişkilendirilen kadim bir anlatının izlerinden doğan seramik heykel serisidir.
INSERT INTO products (slug, title_tr, title_en, description_tr, description_en, category, collection, medium_tr, medium_en, dimensions_tr, dimensions_en, subject_tr, subject_en, artist_id, sort_order, is_visible) VALUES ('sahmaran-ii-iki-doga', 'Şahmaran II – İki Doğa', 'Şahmaran II – Two Natures', 'Şahmaran, Anadolu''nun sözlü kültüründe yüzyıllardır yaşayan; bilgelik, doğa, şifa, sır ve dönüşüm kavramlarıyla ilişkilendirilen kadim bir anlatının izlerinden doğan seramik heykel serisidir.
