INSERT INTO products (slug, title_tr, title_en, description_tr, description_en, category, collection, medium_tr, medium_en, dimensions_tr, dimensions_en, subject_tr, subject_en, artist_id, sort_order, is_visible) VALUES ('dervis', 'Derviş', 'Derviş (The Dervish)', 'Anadolu’nun sözlü kültüründe kuşaktan kuşağa aktarılan masallar; yalnızca düşsel hikâyeler değil, toplumun korkularını, umutlarını, dönüşümlerini ve ortak belleğini taşıyan anlatılardır.
