INSERT INTO products (slug, title_tr, title_en, description_tr, description_en, category, collection, medium_tr, medium_en, dimensions_tr, dimensions_en, subject_tr, subject_en, artist_id, sort_order, is_visible) VALUES ('anadolu-ekininde-guzeller', 'Anadolu Ekininde Güzeller', 'Anadolu Ekininde Güzeller (Beauties of the Anatolian Harvest)', 'Anadolu Ekininde Güzeller, Şeref Doğan’ın Anadolu’nun binlerce yıllık kültürel belleğinden ve bu coğrafyada yaşamış uygarlıkların bıraktığı insan imgelerinden hareketle oluşturduğu seramik heykel serisidir.
INSERT INTO products (slug, title_tr, title_en, description_tr, description_en, category, collection, year, medium_tr, medium_en, dimensions_tr, dimensions_en, form_tr, form_en, subject_tr, subject_en, artist_id, sort_order, is_visible) VALUES ('akarin-deryasi', 'Akar’ın Deryası', 'Akar’ın Deryası (Akar’s Sea)', '“Akar’ın Deryası”, Çimenlik Kalesi Deniz Müzesi’nde bulunan gemi direğinin çevresine, mekâna özel olarak tasarlanmış 24 m² büyüklüğünde bir mimari seramik uygulamadır.
INSERT INTO products (slug, title_tr, title_en, description_tr, description_en, category, collection, year, medium_tr, medium_en, dimensions_tr, dimensions_en, form_tr, form_en, subject_tr, subject_en, artist_id, sort_order, is_visible) VALUES ('bilginin-kaynagi', 'Bilginin Kaynağı', 'Bilginin Kaynağı (The Source of Knowledge)', '“Bilginin Kaynağı”, gözlem, araştırma, öğrenme ve yaşamın bilinmeyen yapısını keşfetme düşüncesinden hareketle oluşturulmuş özgün bir mimari seramik pano uygulamasıdır.
INSERT INTO products (slug, title_tr, title_en, description_tr, description_en, category, collection, year, medium_tr, medium_en, dimensions_tr, dimensions_en, form_tr, form_en, subject_tr, subject_en, artist_id, sort_order, is_visible) VALUES ('gizem-olusum-ve-sonsuzluk', 'Gizem, Oluşum ve Sonsuzluk', 'Gizem, Oluşum ve Sonsuzluk (Mystery, Formation and Infinity)', 'Gizem, Oluşum ve Sonsuzluk, evrensel düzeni, varoluşun başlangıcını ve yaşamın sürekliliğini dairesel formlar, semboller ve katmanlı seramik yüzeyler aracılığıyla yorumlayan anıtsal bir mimari seramik panodur.
INSERT INTO products (slug, title_tr, title_en, description_tr, description_en, category, collection, year, medium_tr, medium_en, dimensions_tr, dimensions_en, form_tr, form_en, subject_tr, subject_en, artist_id, sort_order, is_visible) VALUES ('turk-denizcilerinin-sesi', 'Türk Denizcilerinin Sesi', 'Türk Denizcilerinin Sesi (The Voice of Turkish Seafarers)', '“Türk Denizcilerinin Sesi”, denizciliğin evrensel iletişim dili olan işaret flamalarını seramik yüzey üzerinde bir araya getiren özgün bir mimari seramik pano uygulamasıdır.
